import {ActivityCreationElement} from '@hw/hmiweb-activity-creation/unbundled/index';
import {IActivityCreationElement} from '@hw/hmiweb-activity-creation/unbundled/interfaces/IActivityCreationElement';
import {ActivityCreationDataTypes} from '@hw/hmiweb-activity-creation/unbundled/interfaces/ActivityCreationDataTypes';
import {IActivityCreationAndDataService} from '@hw/experionservices/unbundled/interfaces/IActivityCreationAndDataService';

import {ActivityDataElement} from '@hw/hmiweb-activity-data/unbundled/index';
import {IActivityDataElement} from '@hw/hmiweb-activity-data/unbundled/interfaces/IActivityDataElement';
import {IPointDataService} from '@hw/experionservices/unbundled/interfaces/IPointDataService';
import {ISubscriptionService} from '@hw/experionservices/unbundled/interfaces/ISubscriptionService';

export class ActivityCreationDisplay {
    private _activityCreationElement: HTMLElement & IActivityCreationElement;
    private _activityDataElement: HTMLElement & IActivityDataElement;

    constructor(private _logger: ILogger,
                private _localization: ILocalisation,
                private _activityCreationAndDataService: IActivityCreationAndDataService,
                private _pointDataService: IPointDataService,
                private _pointDataSubscriptionService: ISubscriptionService) {
        this._activityCreationElement = document.getElementById("activityCreation") as any;
        this._activityDataElement = document.getElementById("activityData") as any;
        this.setupListeners();
        ActivityCreationElement.register(this._logger, this._localization, this._activityCreationAndDataService);
        ActivityDataElement.register(this._logger, this._localization, this._activityCreationAndDataService, this._pointDataService, this._pointDataSubscriptionService);
        
        this._logger.info(LogGroups.SPA, "ActivityCreationDisplay .. created");
    }

    private setupListeners(): void {
        this._logger.info(LogGroups.SPA, "ActivityCreationDisplay::setupListeners .. entering");

        if (this._activityCreationElement && this._activityDataElement) {
            this._activityCreationElement.addEventListener("activity-creation-created", () => {
                this.setPopupTitle();
                this.showActivityCreationFromURL();
            });
            this._activityCreationElement.addEventListener("activity-creation-activity-created", (event: Event) => {
                const customEvent = event as CustomEvent<ActivityCreationDataTypes.OnCreationEventData>;
                this.onActivityCreation(customEvent.detail.activityPointName, customEvent.detail.actionOnCreation);
            });
            this._activityDataElement.addEventListener("activity-data-activity-changed", () => {
                this.setPopupTitle();
            });
            this._logger.info(LogGroups.SPA, "ActivityCreationDisplay::setupListeners .. added event listeners");
        } else {
            this._logger.error(LogGroups.SPA, "ActivityCreationDisplay::setupListeners .. couldn't find ActivityCreationElement or ActivityDataElement");
        }
    }

    private showActivityCreationFromURL(): void {
        this._logger.info(LogGroups.SPA, "ActivityCreationDisplay::showActivityCreationFromURL .. entering");

        const queryString = document.location.search;
        let params: string[] = queryString.substring(1).split("&");

        for (let param of params) {
            let parts = param.split(/=(.*)/);

            if (parts[0] == "creationbaselinefilter" && parts.length > 1) {
                const baseFilter = this.getBaseFilter(decodeURIComponent(parts[1]));
                this._logger.info(LogGroups.SPA, `ActivityCreationDisplay::showActivityCreationFromURL .. showing creation UI with base filter: ${JSON.stringify(baseFilter)}`);
                this._activityCreationElement.show(baseFilter.activityType, baseFilter.assets, baseFilter.pointName, baseFilter.pubName);
                return;
            }
        }

        this._activityCreationElement.show(ActivityCreationDataTypes.ActivityType.AllActivities, []);
        this._logger.error(LogGroups.SPA, `ActivityCreationDisplay::showActivityCreationFromURL .. creationbaselinefilter param not found in query string "${document.location.search}"`);
    }

    // helper to extract all the different filters from the SQL formatted filter string and return an object with the filters
    // assumes the aggregation between different SQL substrings for different field is always an AND.
    private getBaseFilter(sql: string): ActivityCreationDataTypes.BaselineFilter {
        this._logger.info(LogGroups.SPA, "ActivityCreationDisplay::getBaseFilter .. entering");

        // regular expressions to extract normal string type filter values
        const FILTERSUBSTR_TAGNAME_FIELD = /Tagname like '([^']+)'/i;
        const FILTERSUBSTR_PUBLICNAME_FIELD = /PublicName like '([^']+)'/i;
        const FILTERSUBSTR_ASSET_FIELD = /Asset like '([^']+)'/i;

        // get the TagName filter
        let tagNameFilter = sql.match(FILTERSUBSTR_TAGNAME_FIELD);
        let tagNameFilterStr = "";
        if ((tagNameFilter != null) && (tagNameFilter.length >= 2)) {
            tagNameFilterStr = tagNameFilter[1];
        }
        this._logger.info(LogGroups.SPA, `ActivityCreationDisplay::getBaseFilter .. set tagname filter to "${tagNameFilterStr}"`);

        // get the PublicName filter
        let publicNameFilter = sql.match(FILTERSUBSTR_PUBLICNAME_FIELD);
        let publicNameFilterStr = "";
        if ((publicNameFilter != null) && (publicNameFilter.length >= 2)) {
            publicNameFilterStr = publicNameFilter[1];
        }
        this._logger.info(LogGroups.SPA, `ActivityCreationDisplay::getBaseFilter .. set public name filter to "${publicNameFilterStr}"`);

        // get the ActivityType filter
        let actTypeFilterEnum = this.getActivityType(sql);

        // get the assets filter
        let assetFilterDelimited = sql.match(FILTERSUBSTR_ASSET_FIELD);
        let assetFilterDelimitedStr = "";
        if ((assetFilterDelimited != null) && (assetFilterDelimited.length >= 2)) {
            assetFilterDelimitedStr = assetFilterDelimited[1];
        }
        let assetsFilter = assetFilterDelimitedStr ? assetFilterDelimitedStr.split(";") : [];
        this._logger.info(LogGroups.SPA, `ActivityCreationDisplay::getBaseFilter .. set assets filter to ${JSON.stringify(assetsFilter)}`);

        return {
            activityType: actTypeFilterEnum,
            assets: assetsFilter,
            pointName: tagNameFilterStr,
            pubName: publicNameFilterStr
        }
    }

    private getActivityType(sql: string): ActivityCreationDataTypes.ActivityType {
        const FILTERSUBSTR_ACTTYPE_BATCHFILTER = /ActivityType like '?Batch/i;
        const FILTERSUBSTR_ACTTYPE_PROCEDUREFILTER = /ActivityType like '?Procedure/i;

        let includeBatches = false;
        let includeProcedures = false;

        if (sql.search(FILTERSUBSTR_ACTTYPE_BATCHFILTER) >= 0) {
            includeBatches = true;
        }

        if (sql.search(FILTERSUBSTR_ACTTYPE_PROCEDUREFILTER) >= 0) {
            includeProcedures = true;
        }

        let actTypeFilter = ActivityCreationDataTypes.ActivityType.AllActivities;	
        if (includeBatches && !includeProcedures) {
            actTypeFilter = ActivityCreationDataTypes.ActivityType.Batch;
        } else if (!includeBatches && includeProcedures) {
            actTypeFilter = ActivityCreationDataTypes.ActivityType.Procedure;
        }

        this._logger.info(LogGroups.SPA, `ActivityCreationDisplay::getActivityType .. set activity type filter to ${actTypeFilter}`);

        return actTypeFilter;
    }

    private setPopupTitle(): void {
        this._logger.info(LogGroups.SPA, "ActivityCreationDisplay::setPopupTitle .. entering");

        this._localization.getLocalisedStrings().then((localisedStrings: ILocalisedStrings) => {
            const localizedTitleStart = `${localisedStrings.getStringOrError("Create")}`;
            const localizedTitleDefault = "...";
            
            if (!this._activityDataElement) {
                document.title = localizedTitleStart + localizedTitleDefault;
                this._logger.error(LogGroups.SPA, `ActivityCreationDisplay::setPopupTitle .. couldn't find ActivityDataElement, using default title`);
                return;
            }
    
            const batchId = this._activityDataElement.batchId;
            const publicName = this._activityDataElement.activityPublicName;
            let title = localizedTitleStart;

            if (!batchId || !publicName) {
                title += localizedTitleDefault;
            } else {
                // \u205f is alternate whitespace for double space, as consecutive whitespaces are collapsed
                title += `: ${batchId} \u205f|\u205f ${publicName}`;
            }

            document.title = title;

            this._logger.info(LogGroups.SPA, `ActivityCreationDisplay::setPopupTitle .. set title to "${title}"`);
        });
    }

    private onActivityCreation(activityPointName: string, actionOnCreation: ActivityCreationDataTypes.ActionOnCreation) {
        this._logger.info(LogGroups.SPA, "ActivityCreationDisplay::onActivityCreation .. entering");

        switch (actionOnCreation) {
            case ActivityCreationDataTypes.ActionOnCreation.EditParameters:
                this._activityCreationElement.hide();
                this._activityDataElement.show(activityPointName);
                break;
            case ActivityCreationDataTypes.ActionOnCreation.StartActivity:
                break;
        }
    }
}
