import { ActivityDataDataTypes } from "../ActivityDataDataTypes";
import { ParamRange } from "./IParamsDataModel";
import { hsc } from "@hw/experionservices/generated/ActivityCreationAndDataMessages.proto";

export const enum ParamValueType {
    Unknown,
    Char,
    Int2,
    Int4,
    Int8,
    Real,
    Dble,
    Hist,
    Enum,
    Time,
    MetadataEnum,
    ReferenceBatch
};

export type ParamMetadata = {
    name?: string;
    type?: string;
    displayName?: string;
    units?: string;
    enumSetId?: string;
    enumSet?: Enumeration[];
    tabType?: ActivityDataDataTypes.ActDataTab;
    order?: number;
    readOnly?: boolean;
    minValue?: ReferenceValue;
    maxValue?: ReferenceValue;
    defaultValue?: ReferenceValue;
    enabledValue?: ReferenceValue;
};

export class Enumeration {
    constructor(private _ordinal: number, private _text: string) { }
    get ordinal(): number { return this._ordinal; }
    get text(): string { return this._text; }
    toString(): string { return this._text; }
}

export type ParamValue = number|string|Long|Enumeration;

export type ReferenceValue = {
    param: string;
    value?: ParamValue;     // value is undefined for if useReference is true and the param value has not been read yet
    useReference: boolean;
    useActEntity: boolean;
}

export interface IParamDataModel {
    dispose(): void;
    init(metadata: ParamMetadata): void;
    setType(type: ParamValueType): void;
    updateValue(val: ParamValue, ipsQuality?: number): void;    // for subscription update
    updateDefaultValue(val: ParamValue): void;                  // for one shot read update
    editValue(val: ParamValue): void;                           // for write edit
    clearValue(): void;
    getEnum(): Promise<Enumeration[]>;
    onWriteComplete(errorInfo: hsc.IErrorInfo, value?: ParamValue, valueType?: ParamValueType): boolean;
    updateMinMax(update: ParamRange): void;

    readonly parameterName: string;
    readonly displayName: string;
    readonly units: string;
    readonly tabType: ActivityDataDataTypes.ActDataTab;
    readonly order: number;
    readonly readOnly: boolean;
    readonly value: ParamValue;
    readonly valueType: ParamValueType;
    readonly ipsQuality: number;
    readonly isEditable: boolean;
    readonly isEdited: boolean;
    readonly default: ReferenceValue;
    readonly defaultValue: string;
    readonly min: ReferenceValue;
    readonly minValue: string;
    readonly max: ReferenceValue;
    readonly maxValue: string;
    readonly error: string;
    readonly uneditedValue: ParamValue;

    readonly valueChangedSubscriber: ISignalSubscriber<() => void>;
    readonly defaultValueChangedSubscriber: ISignalSubscriber<() => void>;
}
